func EnforceMTLS(next http.Handler) http.Handler {
  return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.TLS == nil || len(r.TLS.PeerCertificates) == 0 {
      w.WriteHeader(http.StatusUnauthorized)
      return
    }
    next.ServeHTTP(w, r)
  })
}

export const useTimelineSync = (id) => {
  const query = useQuery({ queryKey: ["timeline", id], queryFn: () => fetchTimeline(id) });
  useEffect(() => {
    const sub = socket.channel(id).on("event", query.refetch);
    return () => sub.unsubscribe();
  }, [id]);
  return query;
};

export const useBreakpoints = () => {
  const [bp, setBp] = useState("md");
  useEffect(() => {
    const listener = () => setBp(window.innerWidth > 1024 ? "lg" : "md");
    window.addEventListener("resize", listener);
    return () => window.removeEventListener("resize", listener);
  }, []);
  return bp;
};

